package mugi.bridge;
import java.awt.Component;import java.awt.Container;import java.awt.Window;import java.lang.instrument.Instrumentation;
import javax.swing.AbstractButton;import javax.swing.JFrame;import javax.swing.SwingUtilities;
public final class CubismMenuClickAgent{public static void agentmain(String argument,Instrumentation ignored){String[]a=argument.split("\\|",-1);SwingUtilities.invokeLater(()->{for(Window w:Window.getWindows())if(w instanceof JFrame f&&f.isVisible()&&f.getTitle().contains(a[0])){AbstractButton b=find(f.getJMenuBar(),a[1]);if(b==null)throw new IllegalStateException("menu not found: "+a[1]);b.doClick();return;}throw new IllegalStateException("window not found");});}private static AbstractButton find(Component c,String text){if(c instanceof AbstractButton b&&text.equals(b.getText()))return b;if(c instanceof javax.swing.JMenu m)for(Component x:m.getMenuComponents()){AbstractButton b=find(x,text);if(b!=null)return b;}if(c instanceof Container n)for(Component x:n.getComponents()){AbstractButton b=find(x,text);if(b!=null)return b;}return null;}}
